//! A from-scratch re-implementation of the subset of `tsl::hopscotch_map`
//! behaviour exercised by the test: `reserve`, `insert`, `size`,
//! `bucket_count` and `overflow_size`.
//!
//! The table uses hopscotch hashing: every bucket carries a bitmap
//! (`hop_info`) describing which of the `NEIGHBORHOOD_SIZE` buckets
//! following it hold entries belonging to its neighbourhood. Insertions
//! that cannot be placed inside their neighbourhood land in an overflow
//! list, mirroring the original container's `overflow_size()`.

use std::hash::{BuildHasherDefault, Hash, Hasher};

/// Number of neighbour buckets tracked by each bucket's hop bitmap.
const NEIGHBORHOOD_SIZE: usize = 62;

/// Identity hasher: mirrors libstdc++'s `std::hash` for integral types,
/// which is the identity function. This keeps bucket placement identical
/// to the C++ binary for integer keys.
#[derive(Default)]
pub struct IdentityHasher {
    hash: u64,
}

impl Hasher for IdentityHasher {
    fn finish(&self) -> u64 {
        self.hash
    }

    fn write(&mut self, bytes: &[u8]) {
        for &byte in bytes {
            self.hash = (self.hash << 8) | u64::from(byte);
        }
    }

    fn write_u8(&mut self, n: u8) {
        self.hash = u64::from(n);
    }

    fn write_u16(&mut self, n: u16) {
        self.hash = u64::from(n);
    }

    fn write_u32(&mut self, n: u32) {
        self.hash = u64::from(n);
    }

    fn write_u64(&mut self, n: u64) {
        self.hash = n;
    }

    fn write_usize(&mut self, n: usize) {
        self.hash = n as u64;
    }

    fn write_i8(&mut self, n: i8) {
        self.hash = n as i64 as u64;
    }

    fn write_i16(&mut self, n: i16) {
        self.hash = n as i64 as u64;
    }

    fn write_i32(&mut self, n: i32) {
        self.hash = n as i64 as u64;
    }

    fn write_i64(&mut self, n: i64) {
        self.hash = n as u64;
    }

    fn write_isize(&mut self, n: isize) {
        self.hash = n as i64 as u64;
    }
}

type IdentityBuildHasher = BuildHasherDefault<IdentityHasher>;

struct Bucket<K, V> {
    /// Bitmap of the neighbourhood slots holding entries for this bucket.
    hop_info: u64,
    entry: Option<(K, V)>,
}

impl<K, V> Bucket<K, V> {
    fn new() -> Self {
        Bucket {
            hop_info: 0,
            entry: None,
        }
    }
}

/// Why an entry could not be placed into the bucket array.
enum PlaceError<K, V> {
    /// No empty bucket exists at all; the table must grow.
    TableFull(K, V),
    /// No free slot could be hopped into the home neighbourhood.
    NoRoom(K, V),
}

pub struct HopscotchMap<K, V> {
    buckets: Vec<Bucket<K, V>>,
    overflow: Vec<(K, V)>,
    len: usize,
    hash_builder: IdentityBuildHasher,
}

/// Number of buckets allocated for a reservation of `count` elements:
/// the smallest power of two strictly greater than `count` (0 for 0).
fn bucket_count_for(count: usize) -> usize {
    if count == 0 {
        0
    } else if count.is_power_of_two() {
        count * 2
    } else {
        count.next_power_of_two()
    }
}

impl<K: Hash + Eq, V> HopscotchMap<K, V> {
    pub fn new() -> Self {
        HopscotchMap {
            buckets: Vec::new(),
            overflow: Vec::new(),
            len: 0,
            hash_builder: IdentityBuildHasher::default(),
        }
    }

    pub fn size(&self) -> usize {
        self.len
    }

    pub fn bucket_count(&self) -> usize {
        self.buckets.len()
    }

    pub fn overflow_size(&self) -> usize {
        self.overflow.len()
    }

    /// Reserve room for `count` elements. Matches the original container:
    /// non-positive reservations leave the table empty.
    pub fn reserve(&mut self, count: usize) {
        let wanted = bucket_count_for(count);
        if wanted > self.buckets.len() {
            self.rehash(wanted);
        }
    }

    pub fn insert(&mut self, key: K, value: V) {
        if let Some(existing) = self.get_mut(&key) {
            *existing = value;
            return;
        }
        if self.buckets.is_empty() {
            self.rehash(2);
        }
        let mut item = (key, value);
        loop {
            let (key, value) = item;
            match self.try_place(key, value) {
                Ok(()) => {
                    self.len += 1;
                    return;
                }
                Err(PlaceError::TableFull(k, v)) => {
                    self.rehash(self.buckets.len() * 2);
                    item = (k, v);
                }
                Err(PlaceError::NoRoom(k, v)) => {
                    self.overflow.push((k, v));
                    self.len += 1;
                    return;
                }
            }
        }
    }

    pub fn get(&self, key: &K) -> Option<&V> {
        if !self.buckets.is_empty() {
            let mask = self.buckets.len() - 1;
            let home = self.hash_of(key) & mask;
            let hops = self.buckets[home].hop_info;
            for d in 0..NEIGHBORHOOD_SIZE {
                if hops & (1 << d) != 0 {
                    let idx = (home + d) & mask;
                    if let Some((k, v)) = &self.buckets[idx].entry {
                        if k == key {
                            return Some(v);
                        }
                    }
                }
            }
        }
        self.overflow.iter().find(|(k, _)| k == key).map(|(_, v)| v)
    }

    pub fn get_mut(&mut self, key: &K) -> Option<&mut V> {
        if !self.buckets.is_empty() {
            let mask = self.buckets.len() - 1;
            let home = self.hash_of(key) & mask;
            let hops = self.buckets[home].hop_info;
            for d in 0..NEIGHBORHOOD_SIZE {
                if hops & (1 << d) != 0 {
                    let idx = (home + d) & mask;
                    if matches!(&self.buckets[idx].entry, Some((k, _)) if k == key) {
                        return self.buckets[idx].entry.as_mut().map(|(_, v)| v);
                    }
                }
            }
        }
        self.overflow
            .iter_mut()
            .find(|(k, _)| k == key)
            .map(|(_, v)| v)
    }

    fn hash_of(&self, key: &K) -> usize {
        let mut hasher = self.hash_builder.build_hasher();
        key.hash(&mut hasher);
        hasher.finish() as usize
    }

    /// Try to place a new entry in the neighbourhood of its home bucket.
    fn try_place(&mut self, key: K, value: V) -> Result<(), PlaceError<K, V>> {
        let len = self.buckets.len();
        let mask = len - 1;
        let home = self.hash_of(&key) & mask;

        // Find the first empty bucket at or after `home` (wrapping around).
        let mut free = None;
        for d in 0..len {
            let idx = (home + d) & mask;
            if self.buckets[idx].entry.is_none() {
                free = Some(idx);
                break;
            }
        }
        let mut free = match free {
            Some(f) => f,
            None => return Err(PlaceError::TableFull(key, value)),
        };

        // Hop the free bucket back until it lies within the neighbourhood.
        while (free + len - home) & mask >= NEIGHBORHOOD_SIZE {
            let mut moved = false;
            // Candidate buckets that could donate an entry to `free`.
            for back in (1..NEIGHBORHOOD_SIZE).rev() {
                let cand = (free + len - back) & mask;
                let hops = self.buckets[cand].hop_info;
                for d in 0..back {
                    if hops & (1 << d) != 0 {
                        let from = (cand + d) & mask;
                        self.buckets[free].entry = self.buckets[from].entry.take();
                        self.buckets[cand].hop_info &= !(1 << d);
                        self.buckets[cand].hop_info |= 1 << back;
                        free = from;
                        moved = true;
                        break;
                    }
                }
                if moved {
                    break;
                }
            }
            if !moved {
                return Err(PlaceError::NoRoom(key, value));
            }
        }

        let dist = (free + len - home) & mask;
        self.buckets[free].entry = Some((key, value));
        self.buckets[home].hop_info |= 1 << dist;
        Ok(())
    }

    fn rehash(&mut self, new_bucket_count: usize) {
        let old = std::mem::replace(
            &mut self.buckets,
            (0..new_bucket_count).map(|_| Bucket::new()).collect(),
        );
        let overflow = std::mem::take(&mut self.overflow);
        self.len = 0;
        for mut bucket in old {
            if let Some((k, v)) = bucket.entry.take() {
                self.insert(k, v);
            }
        }
        for (k, v) in overflow {
            self.insert(k, v);
        }
    }
}

