//! Port of tests/test18.cpp: reserves a hopscotch map, inserts
//! `count` sequential keys and prints `size bucket_count overflow_size`.

#[path = "src/hopscotch_map.rs"]
mod hopscotch_map;

use hopscotch_map::HopscotchMap;

/// Faithful replacement for `std::stoi`: skips leading whitespace, accepts
/// an optional sign, parses the digit prefix and ignores trailing junk.
/// On failure it mimics the C++ runtime: prints the terminate message and
/// aborts (SIGABRT), like an uncaught `std::invalid_argument` /
/// `std::out_of_range` exception.
fn stoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() && (bytes[i] as char).is_whitespace() {
        i += 1;
    }
    let mut negative = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        negative = bytes[i] == b'-';
        i += 1;
    }
    let mut value: i64 = 0;
    let mut any = false;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        value = value.saturating_mul(10).saturating_add((bytes[i] - b'0') as i64);
        any = true;
        i += 1;
    }
    if !any {
        terminate("std::invalid_argument");
    }
    let value = if negative { -value } else { value };
    if value < i32::MIN as i64 || value > i32::MAX as i64 {
        terminate("std::out_of_range");
    }
    value as i32
}

fn terminate(exception: &str) -> ! {
    eprintln!("terminate called after throwing an instance of '{}'", exception);
    eprintln!("  what():  stoi");
    std::process::abort();
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut count: i32 = 18;
    if args.len() > 1 && args[1] == "--a" {
        count = stoi(&args[2]);
    }

    let mut map: HopscotchMap<i32, i32> = HopscotchMap::new();
    if count > 0 {
        map.reserve(count as usize);
