/// Reserve room for `count` elements. Mirrors the original container:
/// it reallocates to `ceil(count / max_load_factor)` rounded up to a
/// power of two; a zero reservation leaves the table empty.
pub fn reserve(&mut self, count: usize) {
    let needed = (count as f32 / MAX_LOAD_FACTOR).ceil() as usize;
    let wanted = round_up_to_power_of_two(needed);
    if wanted > self.buckets.len() {
        self.rehash(wanted);
    }
}

/// Load threshold above which the table doubles in size, computed with
/// the same float arithmetic as the C++ implementation.
fn max_load_threshold(&self) -> usize {
    (self.buckets.len() as f32 * MAX_LOAD_FACTOR) as usize
}

